from moler.device import DeviceFactory
from moler.scheduler import Scheduler
from moler.config.loggers import get_logging_path
from moler.util.moler_test import MolerTest

import datetime
import os
import openpyxl


class CpuCount(object):

    _instance = None

    _column_headers = ("No", "Date", "TC name", "User processes", "System processes", "Not used", "Upgraded nice",
                       "Steal time", "IO operations", "Hardware interrupts", "Software interrupts")
    _column_translator = {
        'user processes': 'User processes',
        'system processes': 'System processes',
        'not used': 'Not used',
        'upgraded nice': 'Upgraded nice',
        'steal time': 'Steal time',
        'IO operations': 'IO operations',
        'hardware interrupts': 'Hardware interrupts',
        'software interrupts': 'Software interrupts',
        'time': 'Date',
        'tc': 'TC name'
    }

    @classmethod
    def get_instance(cls):
        """
        Return instance of cpu counter.

        :return: Instance of this class.
        """
        if cls._instance is None:
            cls._instance = CpuCount()
        return cls._instance

    def __init__(self):
        self._stored = {}
        self._devices = {}
        self._device_translator = {}  # key is real (cloned) name, value is requested name.
        self._interval = 10
        self._job = None
        self._is_robot = None
        self._sample_nr = 0
        self._offset = 0
        self._save_every = 20
        self._file_name = "cpu_stat.xlsx"

    def add_device(self, name, state, clone=True):
        """
        Add device to execute command to measure cpu utilization.

        :param name: name of device.
        :param state: state in which device should be when command is being executed.
        :param clone: Set True to clone device and execute command on cloned connection instead of passed device to
         avoid interference on test results. False to execute command on passed device.
        :return: None
        """
        new_name = name
        device = DeviceFactory.get_device(name)
        if clone:
            new_name = "{}_{}".format("cpu", name)
            device = DeviceFactory.get_cloned_device(source_device=device, new_name=new_name, initial_state=state)
        if not self._is_device_already_added(candidate_name=new_name):
            self._devices[device] = state
            device.goto_state(state=state)
            self._device_translator[new_name] = name

    def start_observer(self):
        """
        Start callback and execute commands to measure cpu utilization periodically.

        :return: None
        """
        if self._job is None:
            self._stored = {}
            if not self._devices:
                MolerTest.warning("User requested getting CPU stats but list of devices is empty. Add at least one"
                                  " device first.")
                return
            for device in self._devices:
                self._stored[device.name] = []
            callback = self._count_callback
            self._job = Scheduler.get_job(callback, self._interval, None, False, 0)
            self._job.start()
            MolerTest.info("Started cpu stats with interval: {} seconds for devices: {}.".format(
                self._interval, self._device_translator.values()))

    def stop_observer(self):
        """
        Stop callback and save MS Excel sheet.

        :return: None
        """
        try:
            if self._job:
                self._job.cancel()
                self._job = None
            self._save_to_xlsx()
        except Exception as ex:
            MolerTest.warning("Cannot save final report to xlsx due to: '{}'".format(ex))

    def set_interval(self, interval):
        """
        Set interval. Execute the method before start.

        :param interval: Interval in seconds.
        :return: None
        """
        self._interval = interval

    def set_every(self, every):
        """
        How many samples between savings to sheets.

        :param every: No of samples.
        :return: None
        """
        self._save_every = every

    def _is_device_already_added(self, candidate_name):
        found = False
        for device in self._devices:
            if candidate_name == device.name:
                found = True
                break
        return found

    def _count_callback(self):
        # preparation
        self._sample_nr += 1
        current_rets = {}
        current_time = datetime.datetime.now()
        tc_name = self._get_current_tc()
        for device in self._devices:
            device_name = device.name
            current_rets[device_name] = {}
            current_rets[device_name]['time'] = current_time
            current_rets[device_name]['tc'] = tc_name

        try:
            # prepare devices to be ready to execute command
            cmds = {}
            for device in self._devices:
                device_name = device.name
                try:
                    device.goto_state(state=self._devices[device], timeout=2)
                    cmd = device.get_cmd(cmd_name="top",
                                         cmd_params={"options": r"-b -d 0.1 -n 2 | grep ^%Cpu\(s\):", 'n': None})
                    cmds[device_name] = cmd
                except Exception:
                    pass

            # execute commands
            for device_name in cmds.keys():
                cmd = cmds[device_name]
                cmd.start(timeout=2)  # Run commands on all devices in parallel

            # store results from commands
            for device_name in cmds.keys():
                try:
                    cmd = cmds[device_name]
                    cmd.await_done(timeout=2)
                    ret = cmd.result()[r'%Cpu']
                    current_rets[device_name].update(ret)
                except Exception:
                    pass
            # store results from commands to dict
            for device_name in current_rets.keys():
                ret = current_rets[device_name]
                self._stored[device_name].append(ret)
        except Exception as ex:
            MolerTest.info("Exception during getting cpu stat:")
            MolerTest.warning(ex)
        if 0 != self._save_every and 0 == self._sample_nr % self._save_every:
            try:
                self._save_to_xlsx()
            except Exception as ex:
                MolerTest.warning("Cannot save current stats to xlsx file. Reason: {}.".format(ex))

    def _check_if_robot(self):
        try:
            from robot.libraries.BuiltIn import BuiltIn
            test_name = BuiltIn().get_variable_value(r"${TEST NAME}")
            suite_name = BuiltIn().get_variable_value(r"${SUITE NAME}")
            if test_name or suite_name:
                self._is_robot = True
        except Exception:
            self._is_robot = False

    def _get_current_tc(self):
        test_name = "NA"
        if self._is_robot is None:
            self._check_if_robot()
        if self._is_robot:
            from robot.libraries.BuiltIn import BuiltIn
            test_name = BuiltIn().get_variable_value(r"${TEST NAME}")
        return test_name

    def _save_to_xlsx(self):
        path = os.path.join(get_logging_path(), self._file_name)

        MolerTest.info("'Saving statistic to: '{}''".format(path))
        wb = openpyxl.Workbook()
        sheet = wb.active
        try:
            wb.remove_sheet(sheet)
        except Exception as ex:
            MolerTest.warning("Cannot remove default sheet.: '{}'".format(ex))

        for device_name in self._stored.keys():
            sheet_name = device_name
            if device_name in self._device_translator:
                try:
                    sheet_name = self._device_translator[device_name]
                except Exception as ex:
                    MolerTest.warning("Cannot get translated device name for '{}'.: '{}'".format(device_name, ex))

            sheet = wb.create_sheet(sheet_name)
            column = 1
            for column_title in CpuCount._column_headers:
                sheet.cell(row=1, column=column).value = column_title
                column += 1
            row = 2
            for measurement in self._stored[device_name]:
                sheet.cell(row=row, column=1).value = row - 1
                for key in measurement:
                    try:
                        translated_column = CpuCount._column_translator.get(key, None)
                    except Exception as ex:
                        MolerTest.warning("Cannot get translated column name for '{}'.: '{}'".format(key, ex))
                    if translated_column:
                        column = CpuCount._column_headers.index(translated_column) + 1
                        sheet.cell(row=row, column=column).value = measurement[key]
                    else:
                        sheet.cell(row=row, column=column).value = "N/A"
                # Date format
                column = CpuCount._column_headers.index("Date") + 1
                sheet.cell(row=row, column=column).number_format = "HH:MM:SS"
                row += 1
        try:
            wb.save(path)
        except Exception as ex:
            MolerTest.warning("Cannot save xlsx to '{}'.: '{}'".format(path, ex))
